'use strict';
window.PilotDetails=async function(push=true){if(!entry?.hasDetails)return;const started=epoch;$('record-title').textContent=currentNode().label;openDialog('record-dialog',push);$('close-record').focus();const body=$('record-body');body.replaceChildren(element('p','Opening book details…'));try{const data=await json('data/'+entry.entityId.replace(':','-')+'/details.json');if(started!==epoch||!$('record-dialog').open)return;addSources(data.sources);body.replaceChildren(element('p',(entry.creators||[]).filter(c=>['author','coauthor'].includes(c.role)).map(c=>c.person.label).join(' · ')+(publicationYear()?' · '+publicationYear():''),'byline'),recordNote(currentNode()));for(const k of ['creators','editions','publications']){const panel=listSection(k,data.sections[k]);if(panel){if(k==='editions')panel.open=true;body.append(panel);}}}catch{if(started===epoch)body.replaceChildren(element('p','Details could not be loaded. Close and try again; your work page remains available.'));}};
